import('./src/patients.mjs').then(m => {
  const testCases = [
    { input: [15, 0, 10], expected: 10 },
    { input: [-3, 0, 10], expected: 0 },
    { input: [5, 0, 10], expected: 5 }
  ];

  console.log('Testing clampInfusionRate:');
  testCases.forEach(tc => {
    const result = m.clampInfusionRate(...tc.input);
    const pass = result === tc.expected;
    console.log(\`  clampInfusionRate(\${tc.input.join(', ')}) = \${result} (expected \${tc.expected}) \${pass ? '✓' : '✗'}\`);
  });
});
